package cn.zj.zjmarket.test.order;

import cn.bugstack.api.v2.*;
import cn.zj.zjmarket.domain.order.adapter.port.ITeamDiscoveryPort;
import cn.zj.zjmarket.domain.order.model.entity.MarketOrder;
import cn.zj.zjmarket.domain.order.model.valobj.*;
import cn.zj.zjmarket.domain.order.service.IOrderService;
import cn.zj.zjmarket.domain.order.service.impl.TeamDiscoveryService;
import cn.zj.zjmarket.domain.product.model.entity.Product;
import cn.zj.zjmarket.domain.product.model.valobj.*;
import cn.zj.zjmarket.domain.product.service.*;
import cn.zj.zjmarket.domain.inventory.model.entity.InventoryAccount;
import cn.zj.zjmarket.domain.inventory.service.IInventoryService;
import cn.zj.zjmarket.infrastructure.adapter.port.order.DubboTeamDiscoveryPort;
import cn.zj.zjmarket.types.exception.ProductFailure;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class TeamDiscoveryBackendTest {
 private static final String NOW="2026-10-14T10:00:00.000Z",END="2026-10-14T10:30:00.000Z";
 private static TeamDiscoveryRequest request(){var r=new TeamDiscoveryRequest();r.setSource("b");r.setChannel("web");r.setUserId("buyer");r.setGoodsId("sku");r.setActivityId("7");r.setProductVersion("1");r.setLimit(3);return r;}
 private static TeamDiscoveryItem item(String id){var i=new TeamDiscoveryItem();i.setTeamId(id);i.setGoodsId("sku");i.setActivityId("7");i.setTeamVersion("1");i.setTeamStatus("FORMING");i.setTargetCount(3);i.setReservedCount(2);i.setPaidCount(1);i.setValidStartTime("2026-10-14T09:00:00.000Z");i.setValidEndTime(END);return i;}
 private static RpcResult<TeamDiscoveryPage> success(TeamDiscoveryItem... items){var p=new TeamDiscoveryPage();p.setSource("b");p.setChannel("web");p.setUserId("buyer");p.setGoodsId("sku");p.setActivityId("7");p.setProductVersion("1");p.setServerTime(NOW);p.setItems(Arrays.asList(items));p.setHasMore(false);return new RpcResult<>("0000","ok",p,"request");}
 private static String code(RpcResult<TeamDiscoveryPage> r){return assertThrows(ProductFailure.class,()->DubboTeamDiscoveryPort.readResponse(r,request(),"request",3)).code();}
 @Test void mapsSafeCountsAndRejectsMutatedPage(){var r=success(item("team-1"));var p=DubboTeamDiscoveryPort.readResponse(r,request(),"request",3);assertEquals(1,p.items().getFirst().availableSlots());assertEquals(2,p.items().getFirst().remainingPaidCount());assertEquals("AVAILABLE",p.state());r.getData().getItems().getFirst().setPaidCount(0);assertEquals("UPSTREAM_RESPONSE_INVALID",code(r));r.getData().getItems().getFirst().setPaidCount(1);r.getData().setUserId("other");assertEquals("UPSTREAM_RESPONSE_INVALID",code(r));}
 @Test void rejectsDuplicatesOrderAndCursorInconsistency(){var r=success(item("team-1"),item("team-1"));assertEquals("UPSTREAM_RESPONSE_INVALID",code(r));r=success(item("team-2"),item("team-1"));assertEquals("UPSTREAM_RESPONSE_INVALID",code(r));r=success(item("team-1"));r.getData().setHasMore(true);assertEquals("UPSTREAM_RESPONSE_INVALID",code(r));}
 @Test void rejectsOverflowVersionAndUnsafeIdentifier(){var r=success(item("team-1"));r.getData().getItems().getFirst().setTeamVersion("9223372036854775808");assertEquals("UPSTREAM_RESPONSE_INVALID",code(r));r.getData().getItems().getFirst().setTeamVersion("1");r.getData().getItems().getFirst().setTeamId("\u0001team");assertEquals("UPSTREAM_RESPONSE_INVALID",code(r));}
 @Test void mapsEveryFrozenErrorClass(){assertEquals("VALIDATION_FAILED",code(new RpcResult<>("0002","",null,"request")));assertEquals("INTEGRATION_AUTH_FAILED",code(new RpcResult<>("E0112","",null,"request")));assertEquals("TEAM_DISCOVERY_CONTEXT_CHANGED",code(new RpcResult<>("PRODUCT_VERSION_CONFLICT","",null,"request")));assertEquals("DEPENDENCY_UNAVAILABLE",code(new RpcResult<>("E0105","",null,"request")));assertEquals("UPSTREAM_RESPONSE_INVALID",code(new RpcResult<>("SURPRISE","",null,"request")));assertEquals("NO_OFFER",DubboTeamDiscoveryPort.readResponse(new RpcResult<>("E0101","",null,"request"),request(),"request",3).reason());assertEquals("PRODUCT_SYNC_PENDING",DubboTeamDiscoveryPort.readResponse(new RpcResult<>("PRODUCT_NOT_FOUND","",null,"request"),request(),"request",3).reason());}
 @Test void firstPageNoOfferBecomesConflictOnCursor(){var q=request();q.setCursor("opaque");assertEquals("TEAM_DISCOVERY_CONTEXT_CHANGED",assertThrows(ProductFailure.class,()->DubboTeamDiscoveryPort.readResponse(new RpcResult<>("E0101","",null,"request"),q,"request",3)).code());}
 @Test void badEnvelopeCannotBecomeEmptySuccess(){assertEquals("UPSTREAM_RESPONSE_INVALID",code(null));assertEquals("UPSTREAM_RESPONSE_INVALID",code(new RpcResult<>("0000","",null,"request")));assertEquals("UPSTREAM_RESPONSE_INVALID",code(new RpcResult<>("E0101","",success().getData(),"request")));assertEquals("UPSTREAM_RESPONSE_INVALID",code(new RpcResult<>("0000","",success().getData(),"other")));}
 @Test void tlsFailureAndConnectionLossAreDistinct(){assertEquals("INTEGRATION_AUTH_FAILED",DubboTeamDiscoveryPort.transport(new RuntimeException(new javax.net.ssl.SSLHandshakeException("bad cert"))).code());assertEquals("DEPENDENCY_UNAVAILABLE",DubboTeamDiscoveryPort.transport(new java.net.ConnectException("down")).code());}
 private record Fixture(IProductService products,IOrderService orders,IInventoryService stock,IMarketingTrialService trial,ITeamDiscoveryPort port,TeamDiscoveryService service) {}
 private static Fixture fixture(){var products=mock(IProductService.class);var orders=mock(IOrderService.class);var stock=mock(IInventoryService.class);var trial=mock(IMarketingTrialService.class);var port=mock(ITeamDiscoveryPort.class);var fields=new ProductFields("sku","",null,"10.00","CNY",SaleStatus.ON_SALE);var view=new ProductView(new Product("sku",fields,1,1,1),new ProductSyncProgress("sku","1","evt","1","CONFIRMED",null,NOW));when(products.detail("sku",false)).thenReturn(view);when(products.detail("sku",true)).thenReturn(view);when(stock.detail("sku")).thenReturn(new InventoryAccount("sku",10,0,0,1,1));when(trial.trial("buyer","sku","request")).thenReturn(new TrialResult("sku","1",NOW,"AVAILABLE",new TrialOffer("7","sku","1","10.00","1.00","9.00","CNY",3)));when(port.list("buyer","sku","7","1",3,3,null,"request")).thenReturn(new DiscoveryPage("AVAILABLE",null,"sku","1","7",NOW,List.of(),null,null,false));return new Fixture(products,orders,stock,trial,port,new TeamDiscoveryService(products,orders,stock,trial,port));}
 @Test void activePurchaseStopsBeforeTrialAndDiscovery(){var f=fixture();var order=mock(MarketOrder.class);when(order.orderId()).thenReturn("my-order");when(f.orders.active("buyer","sku")).thenReturn(order);var p=f.service.list("buyer","sku",3,null,"request");assertEquals("ACTIVE_PURCHASE",p.state());assertEquals("my-order",p.activeOrderId());verifyNoInteractions(f.trial);verify(f.port,never()).list(any(),any(),any(),any(),anyInt(),anyInt(),any(),any());}
 @Test void unavailableStockAndOfferDoNotQueryTeams(){var f=fixture();when(f.stock.detail("sku")).thenReturn(new InventoryAccount("sku",0,0,0,1,1));assertEquals("OUT_OF_STOCK",f.service.list("buyer","sku",3,null,"request").reason());verifyNoInteractions(f.trial);verify(f.port,never()).list(any(),any(),any(),any(),anyInt(),anyInt(),any(),any());var g=fixture();when(g.trial.trial("buyer","sku","request")).thenReturn(new TrialResult("sku","1",NOW,"NO_PUBLIC_OFFER",null));assertEquals("NO_OFFER",g.service.list("buyer","sku",3,null,"request").reason());}
 @Test void productChangeAfterRpcRejectsPage(){var f=fixture();var changed=new ProductView(new Product("sku",new ProductFields("sku","",null,"10.00","CNY",SaleStatus.OFF_SALE),2,1,2),new ProductSyncProgress("sku","2","evt2","2","CONFIRMED",null,NOW));when(f.products.detail("sku",true)).thenReturn(changed);assertEquals("TEAM_DISCOVERY_CONTEXT_CHANGED",assertThrows(ProductFailure.class,()->f.service.list("buyer","sku",3,null,"request")).code());}
 @Test void invalidLimitAndCursorAreCheckedBeforeProduct(){var f=fixture();assertEquals("VALIDATION_FAILED",assertThrows(ProductFailure.class,()->f.service.list("buyer","sku",11,null,"request")).code());doThrow(new ProductFailure(400,"VALIDATION_FAILED")).when(f.port).validateCursor("buyer","sku","bad");assertEquals("VALIDATION_FAILED",assertThrows(ProductFailure.class,()->f.service.list("buyer","sku",3,"bad","request")).code());verifyNoInteractions(f.products);}
}
